package com.nexusdrive.storage.config;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.slf4j.*;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;@Component@Order(1)public class StorageSecurityFilter extends OncePerRequestFilter{private static final Logger log=LoggerFactory.getLogger(StorageSecurityFilter.class);private final byte[] expected;public StorageSecurityFilter(StorageProperties p){if(p.getInternalSecret()==null||p.getInternalSecret().length()<24)throw new IllegalArgumentException("storage.internal-secret must be at least 24 characters");expected=p.getInternalSecret().getBytes(StandardCharsets.UTF_8);log.info("Internal storage authentication configured (credential length {})",expected.length);}protected boolean shouldNotFilter(HttpServletRequest r){String p=r.getRequestURI();return p.equals("/actuator/health")||p.startsWith("/swagger-ui")||p.startsWith("/v3/api-docs");}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String header=r.getHeader("X-Storage-Secret");byte[] actual=header==null?new byte[0]:header.getBytes(StandardCharsets.UTF_8);if(!MessageDigest.isEqual(expected,actual)){log.warn("Rejected storage request with credential length {}",actual.length);s.sendError(HttpServletResponse.SC_UNAUTHORIZED,"Invalid storage credential");return;}c.doFilter(r,s);}}
